  function applicationPreviewMarkup(readiness) {
    var ordered = state.choices.slice().sort(function (a, b) { return Number(a.choice_number) - Number(b.choice_number); });
    var applicant = state.applicant || {}, kin = state.nextOfKin || {}, app = state.application || {};
    function programme(choice) { return choice && state.programmes.find(function (item) { return item.id === choice.programme_id; }); }
    function fact(label, value) { return '<div class="preview-fact"><strong>' + esc(label) + ':</strong> ' + esc(value || 'Not supplied') + '</div>'; }
    function choiceRow(choice, index) { var item = programme(choice); return '<tr><td>' + (index + 1) + '</td><td>' + esc(item && item.programme_code || '—') + '</td><td>' + esc(item && item.programme_name || 'Programme pending') + '</td><td>' + esc(item && item.duration_years ? item.duration_years + ' years' : 'As published by IDMC') + '</td><td>' + esc(choice.status || app.selection_status || 'PENDING') + '</td><td>' + esc(choice.decision_reason || 'Pending review') + '</td></tr>'; }
    var qualificationRows = state.qualifications.map(function (row) { return '<tr><td>' + esc(level(row)) + '</td><td>' + esc(row.index_number || row.registration_number || 'Not provided') + '</td><td>' + esc(row.institution_name || 'Not provided') + '</td><td>' + esc(row.completion_year || '—') + '</td><td>' + esc(row.verification_status || 'PENDING') + '</td></tr>'; }).join('') || '<tr><td colspan="5">No previous education has been added.</td></tr>';
    var academicYear = state.academicYears.find(function (year) { return year.id === app.academic_year_id; });
    var admittedChoice = ordered.find(function (choice) { return ["SELECTED", "ADMISSION_OFFERED", "ACCEPTED"].includes(choice.status); });
    var admittedProgramme = programme(admittedChoice) || ((["ADMISSION_OFFERED", "ACCEPTED", "CONVERTED_TO_STUDENT"].includes(app.status)) ? programme(ordered[0]) : null);
    var applicationTypeLabel = ({ DIPLOMA: "Diploma applicant", CERTIFICATE: "Certificate applicant" })[app.entry_category] || (app.application_type === "CERTIFICATE" ? "Certificate applicant" : "Diploma applicant");
    var statusBlock = readiness ? (readiness.ready ? '<span class="preview-status good">READY TO SUBMIT</span>' : '<ul class="preview-blockers">' + (readiness.blockers || []).map(function (item) { return '<li>' + esc(item) + '</li>'; }).join('') + '</ul>') : '<span class="preview-status">' + esc(app.status || 'PENDING') + '</span>';
    return '<div class="preview-section-grid">' +
      '<section class="preview-section"><h3>Personal details</h3>' + fact('First name', applicant.first_name) + fact('Middle name', applicant.middle_name) + fact('Surname', applicant.last_name) + fact('Gender', applicant.gender) + fact('Birth date', applicant.date_of_birth) + fact('District of birth', applicant.birth_district) + fact('Region of birth', applicant.birth_region) + fact('Country of birth', applicant.birth_country) + fact('Nationality', applicant.nationality) + fact('Marital status', applicant.marital_status) + '</section>' +
      '<section class="preview-section"><h3>Contact and other details</h3>' + fact('Current address', [applicant.address_line_1, applicant.address_line_2, applicant.city, applicant.district, applicant.region, applicant.country].filter(Boolean).join(', ')) + fact('Permanent address', applicant.permanent_address) + fact('National ID', applicant.national_id_number) + fact('Passport', applicant.passport_number) + fact('Phone', applicant.phone) + fact('Email', applicant.email) + fact('Bank', applicant.bank_name) + fact('Bank branch', applicant.bank_branch) + fact('Bank account number', applicant.bank_account_number) + fact('NHIF card number', applicant.nhif_card_number) + fact('Impairment / support', applicant.disability_status ? (applicant.disability_details || 'Support requested') : 'None') + '</section>' +
      '<section class="preview-section"><h3>Next of Kin</h3>' + fact('Name', kin.full_name) + fact('Relationship', kin.relationship) + fact('Occupation', kin.occupation) + fact('Phone', kin.phone) + fact('Email', kin.email) + fact('Address', kin.address) + '</section>' +
      '<section class="preview-section"><h3>Sponsorship</h3>' + fact('Type', app.sponsorship_type) + fact('Sponsor name', app.sponsor_name) + fact('Sponsor occupation', app.sponsor_occupation) + fact('Sponsor phone', app.sponsor_phone) + fact('Sponsor address', app.sponsor_address) + '</section>' +
      '<section class="preview-section"><h3>Application status</h3>' + fact('Application number', app.application_number) + fact('Academic year', academicYear && (academicYear.year_name || academicYear.year_code)) + fact('Entry category', applicationTypeLabel) + fact('Application round', app.application_round) + fact('Eligibility', app.eligibility_status) + fact('Selection', app.selection_status) + fact('Programme admitted', admittedProgramme && admittedProgramme.programme_name || 'Pending') + fact('Remarks', app.review_comments || 'None') + statusBlock + '</section></div>' +
      '<section class="preview-section preview-education"><h3>Education details</h3><div class="preview-table-wrap"><table class="preview-table"><thead><tr><th>Education level</th><th>Index / registration number</th><th>Institution</th><th>Year</th><th>Verification</th></tr></thead><tbody>' + qualificationRows + '</tbody></table></div></section>' +
      '<section class="preview-section preview-choices"><h3>Programme choices</h3><div class="preview-table-wrap"><table class="preview-table"><thead><tr><th>#</th><th>Code</th><th>Programme name</th><th>Duration</th><th>Eligibility status</th><th>Reason</th></tr></thead><tbody>' + (ordered.length ? ordered.map(choiceRow).join('') : '<tr><td colspan="6">Programme choices have not been saved.</td></tr>') + '</tbody></table></div></section>' +
      '<section class="preview-section preview-payment"><h3>Payment details</h3>' + fact('Payment status', app.payment_status || 'PENDING') + fact('Payment reference', app.payment_reference || 'Will appear when issued by Finance') + '</section>';
  }

